.sidebar::-webkit-scrollbar, .main::-webkit-scrollbar, .detail::-webkit-scrollbar { width: 10px; }
.sidebar::-webkit-scrollbar-thumb, .main::-webkit-scrollbar-thumb, .detail::-webkit-scrollbar-thumb {
  background: #d3dae2; border-radius: 5px; border: 2px solid var(--bg);
}

@media (max-width: 1100px) { .detail { width: 320px; } }

