/* LOCI — Open Collection Registry */
:root {
  --bg: #f4f6f9;
  --surface: #ffffff;
  --surface-2: #f8fafc;
  --ink: #17222e;
  --muted: #5c6b7c;
  --faint: #8b98a8;
  --line: #e2e8ef;
  --accent: #4f46e5;
  --accent-soft: #eef0fd;
  --accent-ink: #3730a3;
  --green: #0f8a4d; --green-soft: #e5f6ec;
  --amber: #9a6700; --amber-soft: #fdf3dc;
  --slate: #4c5a68; --slate-soft: #eceff3;
  --danger: #b3382c;
  --radius: 8px;
  --shadow: 0 1px 2px rgba(23, 34, 46, .05), 0 4px 14px rgba(23, 34, 46, .06);
  font-size: 15px;
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0; }
.hidden { display: none !important; }
kbd, .kbd {
  font: 600 11px/1 "Segoe UI", system-ui, sans-serif;
  border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 4px;
  padding: 3px 6px; color: var(--faint); background: var(--surface);
}

#app { display: flex; flex-direction: column; height: 100vh; }

/* ---------- top bar ---------- */
.topbar {
  display: flex; align-items: center; gap: 20px;
  padding: 10px 18px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  flex: none;
}
.brand { display: flex; align-items: baseline; gap: 8px; flex: none; }
.brand-mark { width: 18px; height: 18px; color: var(--accent); align-self: center; }
.brand-name { font-size: 17px; font-weight: 700; letter-spacing: .04em; }
.brand-sub { font-size: 12px; color: var(--muted); }
.search-wrap {
  position: relative; flex: 1; max-width: 640px;
  display: flex; align-items: center;
}
.search-icon {
  position: absolute; left: 12px; width: 15px; height: 15px;
  color: var(--faint); pointer-events: none;
}
#search {
  width: 100%;
  padding: 9px 64px 9px 36px;
  font: inherit; font-size: 14px;
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface-2); color: var(--ink);
  outline: none;
}
#search:focus { border-color: var(--accent); background: var(--surface); box-shadow: 0 0 0 3px var(--accent-soft); }
#search::placeholder { color: var(--faint); }
.search-wrap .kbd { position: absolute; right: 38px; pointer-events: none; }
#search-clear { position: absolute; right: 8px; }
.icon-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; border-radius: 6px; color: var(--muted);
}
.icon-btn:hover { background: var(--slate-soft); color: var(--ink); }
.icon-btn svg { width: 13px; height: 13px; }
.topbar-meta { flex: none; margin-left: auto; }
.total-count { font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }

/* ---------- layout ---------- */
.body { display: flex; flex: 1; min-height: 0; }

/* ---------- sidebar ---------- */
.sidebar {
  width: 252px; flex: none;
  overflow-y: auto;
  background: var(--surface);
  border-right: 1px solid var(--line);
  padding: 14px 10px 30px;
}
.side-title {
  margin: 16px 8px 6px; font-size: 11px; font-weight: 700;
  text-transform: uppercase; letter-spacing: .08em; color: var(--faint);
}
.side-title:first-child { margin-top: 0; }
.tree-row {
  display: flex; align-items: center; gap: 6px;
  width: 100%; text-align: left;
  padding: 6px 8px; border-radius: 6px;
  font-size: 13.5px; color: var(--ink);
}
.tree-row:hover { background: var(--surface-2); }
.tree-row.sel { background: var(--accent-soft); color: var(--accent-ink); font-weight: 600; }
.tree-row .chev { width: 12px; height: 12px; flex: none; color: var(--faint); transition: transform .12s; }
.tree-row .chev.open { transform: rotate(90deg); }
.tree-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tree-count { font-size: 11.5px; color: var(--faint); font-variant-numeric: tabular-nums; }
.tree-row.sel .tree-count { color: var(--accent-ink); }
.tree-cats { margin-left: 18px; border-left: 1px solid var(--line); padding-left: 4px; }
.tree-row.cat { font-size: 13px; padding: 4px 8px; }
.facet-row {
  display: flex; align-items: center; gap: 7px;
  width: 100%; text-align: left;
  padding: 5px 8px; border-radius: 6px; font-size: 13.5px;
}
.facet-row:hover { background: var(--surface-2); }
.facet-row.sel { background: var(--accent-soft); color: var(--accent-ink); font-weight: 600; }
.facet-name { flex: 1; }
.dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.dot-open { background: var(--green); }
.dot-registration { background: #d9a406; }
.dot-gated { background: var(--slate); }

/* ---------- main ---------- */
.main { flex: 1; min-width: 0; overflow-y: auto; padding: 14px 20px 40px; }
.context-bar {
  display: flex; align-items: center; gap: 12px;
  margin-bottom: 8px;
}
.breadcrumb { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; flex-wrap: wrap; }
.crumb { font-size: 13.5px; color: var(--accent); padding: 2px 4px; border-radius: 4px; }
.crumb:hover { background: var(--accent-soft); text-decoration: underline; }
.crumb.here { color: var(--ink); font-weight: 650; cursor: default; }
.crumb.here:hover { background: none; text-decoration: none; }
.crumb-sep { color: var(--faint); font-size: 12px; }
.context-right { display: flex; align-items: center; gap: 8px; flex: none; }
.sort-label { font-size: 12px; color: var(--muted); }
#sort {
  font: inherit; font-size: 13px; color: var(--ink);
  border: 1px solid var(--line); border-radius: 6px;
  padding: 5px 8px; background: var(--surface);
}
.chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 2px 0 6px; }
.chip {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 12.5px; padding: 4px 6px 4px 10px;
  background: var(--accent-soft); color: var(--accent-ink);
  border: 1px solid #dcdffb; border-radius: 999px;
}
.chip svg { width: 11px; height: 11px; opacity: .7; }
.chip:hover svg { opacity: 1; }
.chip-reset { background: var(--surface); color: var(--muted); border-color: var(--line); }
.chip-reset:hover { color: var(--danger); border-color: var(--danger); }
.result-summary {
  margin: 2px 0 10px; font-size: 12.5px; color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* ---------- results ---------- */
.results {
  list-style: none; margin: 0; padding: 0;
  background: var(--surface);
  border: 1px solid var(--line); border-radius: 10px;
  box-shadow: var(--shadow);
  overflow: hidden;
}
.row {
  display: flex; align-items: center; gap: 14px;
  padding: 9px 16px;
  border-bottom: 1px solid var(--line);
  cursor: pointer;
  outline: none;
}
.row:last-child { border-bottom: 0; }
.row:hover { background: var(--surface-2); }
.row[aria-selected="true"] { background: var(--accent-soft); box-shadow: inset 3px 0 0 var(--accent); }
.row:focus-visible { box-shadow: inset 0 0 0 2px var(--accent); }
.row.flash { animation: flash 1.1s ease-out 2; }
@keyframes flash { 0%, 60% { background: #f4e9c8; } 100% { background: var(--accent-soft); } }
.row-main { flex: 1; min-width: 0; }
.row-name { display: block; font-weight: 600; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-sub { display: block; font-size: 12px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }
.row-sub, .detail-id { font-family: ui-monospace, "Cascadia Mono", Consolas, monospace; font-size: 11.5px; }
.row-tags { display: flex; gap: 4px; flex: none; }
.tag {
  font-size: 11px; padding: 2px 8px; border-radius: 999px;
  background: var(--slate-soft); color: var(--slate);
  white-space: nowrap;
}
.row-meta { display: flex; align-items: center; gap: 12px; flex: none; font-size: 12px; color: var(--muted); }
.badge {
  font-size: 11px; font-weight: 600; padding: 2px 8px; border-radius: 5px;
  background: var(--surface-2); border: 1px solid var(--line); color: var(--slate);
  letter-spacing: .02em;
}
.access { font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 999px; text-transform: capitalize; }
.access-open { background: var(--green-soft); color: var(--green); }
.access-registration { background: var(--amber-soft); color: var(--amber); }
.access-gated { background: var(--slate-soft); color: var(--slate); }
.row-size { min-width: 58px; text-align: right; font-variant-numeric: tabular-nums; }
.row-upd { min-width: 68px; text-align: right; font-variant-numeric: tabular-nums; }

.load-more-wrap { text-align: center; margin-top: 14px; }
.load-more {
  font-size: 13px; font-weight: 600; color: var(--accent);
  background: var(--surface); border: 1px solid var(--line);
  border-radius: 999px; padding: 8px 22px;
  box-shadow: var(--shadow);
}
.load-more:hover { border-color: var(--accent); background: var(--accent-soft); }
.end-note { font-size: 12px; color: var(--faint); margin: 4px 0 0; }

.empty {
  background: var(--surface); border: 1px dashed var(--line);
  border-radius: 10px; padding: 44px 20px; text-align: center;
}
.empty-title { font-size: 15px; font-weight: 650; margin: 0 0 6px; }
.empty-sub { font-size: 13px; color: var(--muted); margin: 0 0 16px; }
.btn {
  font-size: 13px; font-weight: 600;
  border: 1px solid var(--line); border-radius: 7px;
  padding: 7px 14px; background: var(--surface);
  color: var(--ink);
}
.btn:hover { border-color: var(--accent); color: var(--accent); }
.btn-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-ink); color: #fff; }

/* ---------- detail ---------- */
.detail {
  width: 380px; flex: none;
  overflow-y: auto;
  background: var(--surface);
  border-left: 1px solid var(--line);
  padding: 18px 22px 40px;
  display: none;
}
.detail.open { display: block; }
.detail-placeholder {
  height: 100%; display: flex; flex-direction: column; gap: 10px;
  align-items: center; justify-content: center; text-align: center;
  color: var(--faint); font-size: 13px; line-height: 1.5;
}
.ph-icon { width: 26px; height: 26px; opacity: .6; }
.detail-head {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 10px;
}
.detail-id { color: var(--accent); font-weight: 600; }
.detail-name { font-size: 18px; line-height: 1.3; margin: 0 0 6px; }
.detail-path { font-size: 12.5px; color: var(--muted); margin: 0 0 12px; }
.detail-badges { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.detail-desc { font-size: 13.5px; line-height: 1.55; color: var(--ink); margin: 0 0 12px; }
.detail-ctx {
  font-size: 12px; color: var(--accent-ink); background: var(--accent-soft);
  border-radius: 6px; padding: 7px 10px; margin: 0 0 16px;
}
.detail-meta {
  display: grid; grid-template-columns: auto 1fr; gap: 6px 18px;
  margin: 0 0 16px; font-size: 13px;
}
.detail-meta dt { color: var(--faint); }
.detail-meta dd { margin: 0; font-variant-numeric: tabular-nums; }
.detail-tags { display: flex; gap: 5px; flex-wrap: wrap; margin-bottom: 20px; }
.detail-actions { display: flex; gap: 8px; }

/* ---------- scrollbars ---------- */
.sidebar::-webkit-scrollbar, .main::-webkit-scrollbar, .detail::-webkit-scrollbar { width: 10px; }
.sidebar::-webkit-scrollbar-thumb, .main::-webkit-scrollbar-thumb, .detail::-webkit-scrollbar-thumb {
