  }

  /* ---------- selection helpers ---------- */
  function rowEl(id) { return document.querySelector('.row[data-id="' + id + '"]'); }

  function revealSelected(flash) {
    var idx = -1;
    var tk = tokens(state.q);
    for (var i = 0; i < ITEMS.length; i++) {
